class BookSerializer(serializers.ModelSerializer):
    price_with_tax = serializers.SerializerMethodField()

    class Meta:
        model = Book
        fields = ["id", "title", "price", "price_with_tax"]

    def get_price_with_tax(self, obj):
        return round(float(obj.price) * 1.10, 2)
